import{_ as r,o as e,c as o,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph Orchestrator Meeting 2020-08-31","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2020-08-31","date":"2020-08-31T00:00:00.000Z","updated":"2020-09-03T00:00:00.000Z","tags":["Ceph Orchestrator","分布式存储","Ceph配置","容器化","配置模板"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/Ceph_Orchestrator_Meeting_2020-08-31.md","filePath":"posts/2020/Ceph_Orchestrator_Meeting_2020-08-31.md","lastUpdated":1780460162000}'),l={name:"posts/2020/Ceph_Orchestrator_Meeting_2020-08-31.md"};function i(s,t,n,h,c,p){return e(),o("div",null,[...t[0]||(t[0]=[a('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-ceph-orchestrator-周会" tabindex="-1">会议主题：Ceph Orchestrator 周会 <a class="header-anchor" href="#会议主题-ceph-orchestrator-周会" aria-label="Permalink to &quot;会议主题：Ceph Orchestrator 周会&quot;">​</a></h4><h4 id="会议时间-2020-08-31" tabindex="-1">会议时间：2020-08-31 <a class="header-anchor" href="#会议时间-2020-08-31" aria-label="Permalink to &quot;会议时间：2020-08-31&quot;">​</a></h4><h4 id="参会人员-参会人员名单" tabindex="-1">参会人员：[参会人员名单] <a class="header-anchor" href="#参会人员-参会人员名单" aria-label="Permalink to &quot;参会人员：[参会人员名单]&quot;">​</a></h4><h4 id="主要议题及讨论内容" tabindex="-1">主要议题及讨论内容： <a class="header-anchor" href="#主要议题及讨论内容" aria-label="Permalink to &quot;主要议题及讨论内容：&quot;">​</a></h4><ol><li><p><strong>NFS 集成问题</strong></p><ul><li><strong>问题概述</strong>：存在两个不兼容的NFS管理实现，分别在Dashboard和Volumes NFS模块中，导致无法并行使用。</li><li><strong>解决方案</strong>：讨论迁移用户从Nautilus到Octopus的方法，寻找自动化的迁移工具。</li><li><strong>行动计划</strong>：继续讨论并寻找解决方案。</li></ul></li><li><p><strong>ceph.conf 生成问题</strong></p><ul><li><strong>问题描述</strong>：config generate minimal conf 生成的 ceph.conf 文件不完整。</li><li><strong>解决方案</strong>：提供扩展 ceph.conf 的方法或改进生成 minimal conf 的功能。</li><li><strong>行动计划</strong>：希望尽快合并解决方案。</li></ul></li><li><p><strong>容器中的 PID 1 问题</strong></p><ul><li><strong>问题描述</strong>：Ceph 容器中的 PID 1 处理不当，导致僵尸进程和无法创建核心文件。</li><li><strong>解决方案</strong>：建议使用 Docker 和 systemd-nspawn 的 <code>--init</code> 标志。</li><li><strong>行动计划</strong>：考虑在发行版中默认启用此设置，并在其他发行版中提供安装依赖包的指导。</li></ul></li><li><p><strong>配置模板问题</strong></p><ul><li><strong>问题描述</strong>：配置模板硬编码在代码中，无法灵活修改。</li><li><strong>解决方案</strong>：建议使用配置密钥存储来覆盖这些模板。</li><li><strong>行动计划</strong>：继续讨论是否有实际需求来推动这一改变。</li></ul></li><li><p><strong>Ceph Orchestrator 模块开发</strong></p><ul><li><strong>进展</strong>：可以在不预先创建环境或编译 Ceph 的情况下，直接开始开发 Ceph Orchestrator 模块。</li><li><strong>行动计划</strong>：鼓励开发者利用这一改进进行模块开发。</li></ul></li><li><p><strong>Ceph Orchestrator 二进制文件重构</strong></p><ul><li><strong>目标</strong>：讨论如何逐步重构 Ceph Orchestrator 二进制文件，以提高代码的可维护性和模块化。</li><li><strong>行动计划</strong>：建议从简化 bootstrap 命令开始，逐步引入类和模块化。</li></ul></li></ol><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>继续讨论和解决 NFS 集成问题，特别是迁移用户的问题。</li><li>合并并实施 ceph.conf 生成问题的解决方案。</li><li>在支持的发行版中默认启用 <code>--init</code> 标志，并在其他发行版中提供安装依赖包的指导。</li><li>根据实际需求，决定是否实施配置模板的灵活修改方案。</li><li>逐步重构 Ceph Orchestrator 二进制文件，提高代码质量和可维护性。</li></ul><h4 id="会议总结" tabindex="-1">会议总结： <a class="header-anchor" href="#会议总结" aria-label="Permalink to &quot;会议总结：&quot;">​</a></h4><p>本次会议主要讨论了 Ceph Orchestrator 相关的多个技术问题和解决方案，涉及 NFS 集成、配置文件生成、容器中的 PID 1 处理、配置模板灵活性以及代码重构等方面。会议确定了后续的行动计划，并鼓励团队成员积极参与到这些改进工作中。</p>',10)])])}const u=r(l,[["render",i]]);export{d as __pageData,u as default};
